DROP TABLE IF EXISTS `societes`;
CREATE TABLE IF NOT EXISTS `societes` (
  `id_societe` int NOT NULL AUTO_INCREMENT,
  `nom_societe` varchar(150) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci NOT NULL,
  `compte_contribuable` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `numero_rcc` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `regime_imposition` enum('Réel Normal','Réel Simplifié','Micro-entreprise') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'Réel Normal',
  `service_impots` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `adresse_complete` text CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci,
  `nom_banque` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `code_guichet` varchar(10) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `numero_compte` varchar(20) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `cle_rib` varchar(5) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `code_swift` varchar(15) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dgi_api_key` varchar(100) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dgi_ifu` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dgi_nim` varchar(50) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `dgi_mode` enum('test','production') CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT 'test',
  `dgi_actif` tinyint(1) DEFAULT '0',
  `logo_societe` varchar(255) CHARACTER SET utf8mb4 COLLATE utf8mb4_general_ci DEFAULT NULL,
  `plan_actuel_id` int DEFAULT NULL,
  `abonnement_expire_le` date DEFAULT NULL,
